  [ -z "$api_endpoint" ] && api_endpoint=$(echo "$input" | grep -o '"apiBaseUrl"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/.*"apiBaseUrl"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/')
