# ---- Port status check (fast, no PM2) ----
check_port_status() {
  local port="$1"
  local pid=$(lsof -t -i :"$port" -sTCP:LISTEN 2>/dev/null | head -1)
  if [ -n "$pid" ]; then
    echo "up"
  else
    echo "down"
  fi
}

get_worktree_from_port() {
  local port="$1"
  local pid=$(lsof -t -i :"$port" -sTCP:LISTEN 2>/dev/null | head -1)
  if [ -n "$pid" ]; then
    local cwd=$(lsof -a -p "$pid" -d cwd -Fn 2>/dev/null | grep ^n | cut -c2-)
    echo "$cwd" | grep -oE 'intexuraos-[0-9]+' || echo ""
  fi
}

