    dev_up=$((dev_up + 1))
    [ -z "$dev_worktree" ] && dev_worktree=$(get_worktree_from_port "$port")
  else
    [ -n "$dev_down_list" ] && dev_down_list="${dev_down_list},"
    dev_down_list="${dev_down_list}${name}"
  fi
done

