    else
      line4="📊 $(usage_color)${tot_tokens} tok (${tpm_formatted} tpm)$(rst)"
    fi
  else
    if [ -n "$line4" ]; then
      line4="$line4  📊 $(usage_color)${tot_tokens} tok$(rst)"
    else
      line4="📊 $(usage_color)${tot_tokens} tok$(rst)"
    fi
  fi
fi

# Print lines
if [ -n "$line2" ]; then
